def comb_sort(nums):
    """Sort a list of elements using comb sort and return the sorted list."""
    n = len(nums)
    gap = n
    swapped = True
    while gap > 1 or swapped:
        gap = max(1, int(gap / 1.3))
        swapped = False
        for i in range(n - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                swapped = True
    return nums

def is_samepatterns(colors, patterns):
    """
    Check whether the list `colors` follows the same pattern given by
    `patterns`, i.e. there is a one-to-one (bijective) mapping between
    pattern elements and string elements.

    >>> is_samepatterns(["red","green","green"], ["a", "b", "b"])
    True
    """
    if len(colors) != len(patterns):
        return False

    # A bijection requires the same number of distinct elements on both sides.
    if len(set(colors)) != len(set(patterns)):
        return False

    mapping = {}
    for pat, col in zip(patterns, colors):
        if pat not in mapping:
            mapping[pat] = col
        elif mapping[pat] != col:
            return False
    return True

