def amicable_numbers_sum(limit):
    """Sum all amicable numbers from 1 to `limit` (inclusive).

    Two numbers a and b are amicable if the sum of the proper divisors
    of a equals b, and the sum of the proper divisors of b equals a,
    with a != b.
    """
    def sum_proper_divisors(n):
        if n <= 1:
            return 0
        total = 1  # 1 divides every n > 1
        i = 2
        while i * i <= n:
            if n % i == 0:
                total += i
                partner = n // i
                if partner != i:
                    total += partner
            i += 1
        return total

    amicable_sum = 0
    for n in range(1, limit + 1):
        m = sum_proper_divisors(n)
        if m != n and sum_proper_divisors(m) == n:
            amicable_sum += n
    return amicable_sum

