def max_sub_array_sum_repeated(a, n, k):
    """Find the largest sum of a contiguous subarray in the modified array
    formed by repeating the given array ``a`` (of length ``n``) ``k`` times.

    Runs in O(n) time using Kadane's algorithm together with prefix/suffix
    sums, so it works even when ``k`` is very large.

    Example:
        >>> max_sub_array_sum_repeated([10, 20, -30, -1], 4, 3)
        30
    """
    if not a or not n or not k:
        return 0
    if n > len(a):
        n = len(a)
    arr = list(a[:n])

    def kadane(values):
        best = cur = values[0]
        for x in values[1:]:
            cur = x if cur < 0 else cur + x
            if cur > best:
                best = cur
        return best

    # Best subarray lying entirely inside a single copy.
    single = kadane(arr)
    if k == 1:
        return single

    total = sum(arr)

    # Best non-empty prefix sum and suffix sum of one copy.
    max_prefix, cur = arr[0], 0
    for x in arr:
        cur += x
        if cur > max_prefix:
            max_prefix = cur
    max_suffix, cur = arr[-1], 0
    for x in reversed(arr):
        cur += x
        if cur > max_suffix:
            max_suffix = cur

    # Best subarray spanning the boundary between two consecutive copies:
    # a suffix of one copy followed by a prefix of the next.
    spanning = max_prefix + max_suffix

    if total > 0:
        # Extra full copies only add (positive) value, so stretch the
        # spanning subarray across all k copies.
        return max(single, spanning + (k - 2) * total)
    # Otherwise the spanning subarray is best kept at exactly two copies.
    return max(single, spanning)

