def set_left_most_unset_bit(n):
    """Set the leftmost (most significant) unset bit of n.

    Example: 10 = 0b1010 -> leftmost unset bit is at position 2 -> 0b1110 = 14.
    If n has no unset bit within its representation (all ones, e.g. 7 = 0b111),
    n is returned unchanged.
    """
    if not (n & (n + 1)):
        # n is all ones (or 0 handled below); no unset bit inside its bits
        if n == 0:
            return 1
        return n
    pos, temp, count = 0, n, 0
    while temp:
        if not (temp & 1):
            pos = count
        count += 1
        temp >>= 1
    return n | (1 << pos)


