def cal_sum(n):
    """Calculate the sum of Perrin numbers P(0) through P(n).

    Perrin sequence: P(0)=3, P(1)=0, P(2)=2, and P(n) = P(n-2) + P(n-3).
    Sequence: 3, 0, 2, 3, 2, 5, 5, 7, 10, 12, ...

    Example: cal_sum(9) == 49  (3+0+2+3+2+5+5+7+10+12)
    """
    if n < 0:
        return 0
    perrin = [3, 0, 2]
    if n < 2:
        return sum(perrin[:n + 1])
    for i in range(3, n + 1):
        perrin.append(perrin[i - 2] + perrin[i - 3])
    return sum(perrin)


if __name__ == "__main__":
    assert cal_sum(9) == 49, cal_sum(9)
    assert cal_sum(0) == 3
    assert cal_sum(1) == 3
    assert cal_sum(2) == 5
    assert cal_sum(3) == 8
    print("All tests passed.")

def sumofFactors(n):
    """Return the sum of the even factors of n."""
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i % 2 == 0:
                total += i
            other = n // i
            if other != i and other % 2 == 0:
                total += other
        i += 1
    return total


