def tuple_intersection(test_list1, test_list2):
    """
    Find the tuple intersection of elements in the given tuple lists,
    irrespective of the order of elements within each tuple.

    A tuple from the first list is included in the result (in its
    original form) if some tuple in the second list contains exactly
    the same elements, regardless of ordering.

    >>> tuple_intersection([(3, 4), (5, 6), (9, 10), (4, 5)],
    ...                    [(5, 4), (3, 4), (6, 5), (9, 11)])
    {(4, 5), (3, 4), (5, 6)}
    """
    # Normalize each tuple in the second list by sorting its elements,
    # so order-insensitive membership checks are simple set lookups.
    normalized2 = {tuple(sorted(t)) for t in test_list2}

    result = set()
    for t in test_list1:
        if tuple(sorted(t)) in normalized2:
            result.add(t)
    return result


