def find_combinations(test_list):
    """Find the combinations of sums with tuples in the given tuple list.

    For every pair of tuples (i < j) in the input list, produce a tuple
    containing the element-wise sums of the two tuples.
    """
    res = []
    for i in range(len(test_list)):
        for j in range(i + 1, len(test_list)):
            res.append(tuple(map(sum, zip(test_list[i], test_list[j]))))
    return res


