    """Check whether the count of divisors of n is even.

    Returns True if n has an even number of divisors, False otherwise.
    """
    count = 0
    for i in range(1, n + 1):
        if n % i == 0:
            count += 1
    return count % 2 == 0

def tuple_str_int(tuple_string):
    """Convert a tuple string like "(7, 8, 9)" to an integer tuple (7, 8, 9)."""
    inner = tuple_string.strip()
    if inner.startswith("("):
        inner = inner[1:]
    if inner.endswith(")"):
        inner = inner[:-1]
    inner = inner.strip()
    if not inner:
        return ()
    return tuple(int(part.strip()) for part in inner.split(",") if part.strip())


if __name__ == "__main__":
    assert tuple_str_int("(7, 8, 9)") == (7, 8, 9)
    assert tuple_str_int("(1, 2, 3)") == (1, 2, 3)
    assert tuple_str_int("(10, -4, 0)") == (10, -4, 0)
    assert tuple_str_int("(5,)") == (5,)
    assert tuple_str_int("()") == ()
    print("All tests passed.")

