def max_run_uppercase(s: str) -> int:
    """Find the maximum run (length) of consecutive uppercase characters in a string."""
    max_run = 0
    current = 0
    for ch in s:
        if ch.isupper():
            current += 1
            if current > max_run:
                max_run = current
        else:
            current = 0
    return max_run


